// Entrada: un ítem por archivo leído de /data/proyecto (config/*.json, schemas/*.json, prompts/*.md).
const archivos = {};
const entrada = $input.all();
for (let i = 0; i < entrada.length; i++) {
  const bin = entrada[i].binary && entrada[i].binary.data;
  if (!bin) continue;
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  archivos[bin.fileName] = buf.toString('utf8');
}
for (const nombre of ['parametros.json', 'fuentes.json', 'descubrimiento.json', 'caso.schema.json', 'busqueda.md', 'extraccion.md', 'clasificacion.md']) {
  if (!(nombre in archivos)) throw new Error(`Falta el archivo ${nombre} en /data/proyecto. Revisa los volúmenes de docker-compose.yml.`);
}

const MARCAS = /^(utm_|fbclid|gclid|mc_cid|mc_eid|ocid|xtor|cmp|ref$|ref_|source$|spm|igshid)/i;

function quitarHtml(s) {
  return String(s || '')
    .replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#0?39;|&apos;/g, "'").replace(/&hellip;/g, '…')
    .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(Number(n)))
    .replace(/\s+/g, ' ').trim();
}

// El global URL no existe en el sandbox de los nodos Code de n8n: se analiza la URL con una expresión regular.
function partesUrl(u) {
  const m = String(u || '').trim().match(/^https?:\/\/([^\/?#:]+)(?::\d+)?([^?#]*)(?:\?([^#]*))?/i);
  return m ? { host: m[1].toLowerCase().replace(/^www\./, ''), ruta: m[2] || '', consulta: m[3] || '' } : null;
}

function hostDe(u) {
  const p = partesUrl(u);
  return p ? p.host : '';
}

// Misma noticia con distinto utm_*, www, fragmento o barra final → misma clave.
function normalizarUrl(u) {
  const p = partesUrl(u);
  if (!p) return String(u || '').trim().toLowerCase();
  const params = p.consulta.split('&').filter(x => x && !MARCAS.test(x.split('=')[0])).sort();
  return p.host + p.ruta.replace(/\/+$/, '') + (params.length ? '?' + params.join('&') : '');
}

function fechaIso(v) {
  const t = Date.parse(v || '');
  return isNaN(t) ? null : new Date(t).toISOString();
}

// Hash estable (cyrb53) de la URL normalizada; sirve como id del caso.
function hash(s) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 2654435761);
    h2 = Math.imul(h2 ^ c, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return 'c' + (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36);
}

const parametros = JSON.parse(archivos['parametros.json']);
const PROVEEDOR = 'anthropic'; // proveedor de IA con el que se generó este workflow
parametros.proveedor_ia = PROVEEDOR;
for (const t of Object.keys(parametros.modelos)) parametros.modelos[t] = parametros.modelos[t][PROVEEDOR];
const desc = JSON.parse(archivos['descubrimiento.json']);
const fuentes = JSON.parse(archivos['fuentes.json']).fuentes.filter(f => f.activa);

// Dominios que ya se vigilan por RSS (el campo "dominio" de fuentes.json; si falta, el host del feed) + dominios sin valor.
const dominiosFuentes = [...new Set(fuentes.map(f => (f.dominio || hostDe(f.feed_url)).toLowerCase()))];
const bloqueados = [...new Set([...dominiosFuentes, ...desc.excluir_dominios])];

// Todas las combinaciones región × tipo; cada ejecución toma N consecutivas, rotando por semana.
const sectorClave = parametros.sector_foco;
const sectorTxt = lang => (sectorClave && desc.sectores[sectorClave] ? ` del sector ${desc.sectores[sectorClave][lang]}` : '');
const combinaciones = [];
for (const r of desc.regiones) {
  for (const t of desc.tipos) {
    const lang = r.idioma;
    const texto = desc.plantillas[lang]
      .replace('{tipo}', t[lang]).replace('{region}', r[lang]).replace('{sector}', sectorTxt(lang));
    combinaciones.push({
      consulta_id: `${r.clave}.${t.clave}`, consulta: texto, region: r[lang], region_nombre: r.nombre, tipo: t[lang], idioma: lang,
      sector: sectorClave && desc.sectores[sectorClave] ? desc.sectores[sectorClave][lang] : 'ninguno',
    });
  }
}
const n = Math.min(desc.consultas_por_ejecucion, combinaciones.length);
const semana = Math.floor(Date.now() / (7 * 86400000));
const inicio = (semana * n) % combinaciones.length;
const consultas = Array.from({ length: n }, (_, i) => combinaciones[(inicio + i) % combinaciones.length]);

return [{
  json: {
    run_id: 'd-' + Date.now().toString(36),
    inicio_iso: new Date().toISOString(),
    ventana_dias: 14,
    parametros,
    descubrimiento: desc,
    schema: JSON.parse(archivos['caso.schema.json']),
    prompts: { busqueda: archivos['busqueda.md'], extraccion: archivos['extraccion.md'], clasificacion: archivos['clasificacion.md'] },
    fuentes: [],
    dominios_fuentes: dominiosFuentes,
    dominios_bloqueados: bloqueados,
    consultas,
    n_combinaciones: combinaciones.length,
  },
}];

// Una sola salida con las URLs ya guardadas como casos (la hoja puede estar vacía).
const urls = $input.all().map(i => i.json.url_normalizada).filter(Boolean);
return [{ json: { urls } }];

// Une las URLs de "casos" y de "descartados": un artículo descartado no se vuelve a pagar al día siguiente.
const casos = $('URLs conocidas (casos)').first().json.urls;
const descartadas = $input.all().map(i => i.json.url_normalizada).filter(Boolean);
return [{
  json: {
    n_casos: casos.length,
    n_descartados: descartadas.length,
    urls: [...new Set([...casos, ...descartadas])],
  },
}];

// Un ítem por consulta de búsqueda; el nodo de IA las procesa de una en una (concurrencia 1, para no disparar el coste).
const cfg = $('Cargar configuración').first().json;
return cfg.consultas.map(c => ({ json: c }));

// Monta el mensaje de sistema y el de usuario a partir del archivo prompts/busqueda.md
const cfg = $('Cargar configuración').first().json;

function partir(md) {
  const limpio = md.replace(/<!--[\s\S]*?-->/g, '');
  const iSys = limpio.indexOf('## SYSTEM');
  const iUsr = limpio.indexOf('## USER');
  if (iSys < 0 || iUsr < 0) throw new Error('El prompt debe tener las secciones "## SYSTEM" y "## USER"');
  return { sistema: limpio.slice(iSys + 9, iUsr).trim(), usuario: limpio.slice(iUsr + 7).trim() };
}
// Una sola pasada: lo que se inserta no se vuelve a interpretar como marcador.
const rellenar = (t, v) => t.replace(/\{\{(\w+)\}\}/g, (m, k) => (v[k] === undefined || v[k] === null ? '' : String(v[k])));

const { sistema, usuario } = partir(cfg.prompts.busqueda);
return $input.all().map(it => {
  const j = it.json;
  const vars = { consulta: j.consulta, region: j.region, tipo: j.tipo, sector: j.sector, idioma: j.idioma, max_candidatos: cfg.descubrimiento.max_candidatos_por_consulta, fecha_hoy: new Date().toISOString().slice(0, 10) };
  return { json: { ...j, prompt_system: sistema, prompt_user: rellenar(usuario, vars) } };
});

// SIMULADO (sin clave de API ni búsqueda web): imita la respuesta del nodo Anthropic con la herramienta web_search.
//   consulta 0 → 3 resultados válidos + 1 de un dominio ya vigilado + 1 enlace que el modelo cita pero NO está en los resultados
//   consulta 1 → un enlace repetido de la consulta 0 y uno nuevo
//   consulta 2 → error de la API
//   consulta 3 → el modelo no devuelve JSON (se usan los resultados tal cual)
//   consultas 4 y 5 → sin resultados
const U = {"A":"https://www.marktechpost.com/2026/10/15/liquid-ai-d1-ultra-decision-model/","B":"https://www.marktechpost.com/2026/10/15/meta-muse-spark-open-816b-open-weight-model/","C":"https://huggingface.co/blog/reflection-beam","D":"https://huggingface.co/blog/nvidia/scaling-indic-pretraining","FUENTE_CONOCIDA":"https://www.xataka.com/robotica-e-ia/openai-pidio-a-ia-que-terminara-tarea-programacion-acabo-entrando-cartera-ajena-para-conseguirlo"};
const resultado = (url, titulo, edad) => ({ type: 'web_search_result', url, title: titulo, page_age: edad, encrypted_content: 'x' });
const bloque = (...rs) => [{ type: 'server_tool_use', name: 'web_search', input: {} }, { type: 'web_search_tool_result', content: rs }];
const texto = (...cands) => ({ type: 'text', text: JSON.stringify({ candidatos: cands.map(([url, titular]) => ({ url, titular, motivo: '(simulado) Caso de ejemplo' })) }) });
const respuestas = [
  [...bloque(resultado(U.A, 'Liquid AI presenta un modelo de decisión', 'October 15, 2026'), resultado(U.B, 'Meta lanza un modelo abierto', 'October 15, 2026'), resultado(U.FUENTE_CONOCIDA, 'Artículo de Xataka', 'October 16, 2026'), resultado(U.C, 'Reflection beam', null)),
    texto([U.A, 'Liquid AI presenta un modelo de decisión'], [U.B, 'Meta lanza un modelo abierto'], [U.FUENTE_CONOCIDA, 'Artículo de Xataka'], ['https://enlace-inventado.example/no-esta-en-los-resultados', 'Inventado'])],
  [...bloque(resultado(U.B, 'Meta lanza un modelo abierto', 'October 15, 2026'), resultado(U.D, 'Preentrenamiento para lenguas indias', 'October 14, 2026')),
    texto([U.B, 'Meta lanza un modelo abierto'], [U.D, 'Preentrenamiento para lenguas indias'])],
  null,
  [...bloque(resultado(U.C, 'Reflection beam', null), resultado(U.A, 'Liquid AI presenta un modelo de decisión', 'October 15, 2026')),
    { type: 'text', text: 'Aquí tienes los enlaces que he encontrado, sin formato JSON.' }],
  [{ type: 'text', text: JSON.stringify({ candidatos: [] }) }],
  [{ type: 'text', text: JSON.stringify({ candidatos: [] }) }],
];
return $input.all().map((it, k) => {
  const r = respuestas[k];
  return { json: r ? { content: r } : { error: 'overloaded_error (simulado)' }, pairedItem: { item: k } };
});

// Convierte la respuesta de la búsqueda web en artículos candidatos.
// Solo se aceptan URLs que aparecen de verdad en los resultados de la herramienta de búsqueda: el modelo elige, pero no puede inventar enlaces.
const cfg = $('Cargar configuración').first().json;
const max = cfg.descubrimiento.max_candidatos_por_consulta;
const MARCAS = /^(utm_|fbclid|gclid|mc_cid|mc_eid|ocid|xtor|cmp|ref$|ref_|source$|spm|igshid)/i;

