    .replace(/&quot;/g, '"').replace(/&#0?39;|&apos;/g, "'").replace(/&hellip;/g, '…')
    .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(Number(n)))
    .replace(/\s+/g, ' ').trim();
