      acceso: j.acceso, destino: falloApi ? 'omitidos' : 'descartados', etapa: 'extraccion', motivo: String(motivo).slice(0, 300),
    },
  };
});

// Marca el artículo para la hoja "descartados". Datos mínimos: no se guarda el texto del artículo.
// Si la causa es un fallo de la API de IA (sin respuesta), el artículo se "omite": no se guarda y se reintentará en la siguiente ejecución.
return $input.all().map(it => {
  const j = it.json;
  const motivo = j.extraccion.motivo_no_caso || 'No es un caso de innovación con IA';
  const falloApi = (j.errores_validacion || []).some(e => e.startsWith('Sin respuesta del modelo'));
  return {
    json: {
      id: j.id, url: j.url, url_normalizada: j.url_normalizada, titular: j.titular, fuente: j.fuente,
      acceso: j.acceso, destino: falloApi ? 'omitidos' : 'descartados', etapa: 'es_caso', motivo: String(motivo).slice(0, 300),
    },
  };
});

// Monta el mensaje de sistema y el de usuario a partir del archivo prompts/clasificacion.md
const cfg = $('Cargar configuración').first().json;

function partir(md) {
  const limpio = md.replace(/<!--[\s\S]*?-->/g, '');
  const iSys = limpio.indexOf('## SYSTEM');
  const iUsr = limpio.indexOf('## USER');
  if (iSys < 0 || iUsr < 0) throw new Error('El prompt debe tener las secciones "## SYSTEM" y "## USER"');
  return { sistema: limpio.slice(iSys + 9, iUsr).trim(), usuario: limpio.slice(iUsr + 7).trim() };
}
// Una sola pasada: lo que se inserta no se vuelve a interpretar como marcador.
const rellenar = (t, v) => t.replace(/\{\{(\w+)\}\}/g, (m, k) => (v[k] === undefined || v[k] === null ? '' : String(v[k])));

const { sistema, usuario } = partir(cfg.prompts.clasificacion);
return $input.all().map(it => {
  const j = it.json;
  const vars = { sector_foco: cfg.parametros.sector_foco || 'ninguno', extraccion_json: JSON.stringify(j.extraccion, null, 1) };
  return { json: { ...j, prompt_system: sistema, prompt_user: rellenar(usuario, vars) } };
});

// SIMULADO (sin clave de API). El último artículo recibe una puntuación fuera de rango para probar el descarte.
const n = $input.all().length;
return $input.all().map((it, k) => {
  const cls = { categoria: 'otros', novedad: 3, impacto: 3, replicabilidad: 3, evidencia: 2, relevancia_sector: null, etiquetas: ['simulado', 'prueba'], justificacion: '(simulado) Puntuación de prueba generada por el mock, no por Claude.' };
  if (n > 2 && k === n - 1) cls.impacto = 9;
  return { json: { content: [{ type: 'text', text: JSON.stringify(cls) }] }, pairedItem: { item: k } };
});

// Valida la clasificación, calcula la puntuación total (pesos en parametros.json) y construye el caso final.
// Validador mínimo de JSON Schema (sin dependencias) para usar igual en local y dentro de un nodo Code de n8n.
// Soporta: $ref local (#/$defs/...), type (string o lista), enum, required, properties,
// additionalProperties:false, items, minimum, maximum, maxLength, maxItems, oneOf.
// Uso local: node scripts/validar_esquema.js <extraccion|clasificacion|metadatos> <fichero.json>

function resolver(raiz, ref) {
  return ref.replace(/^#\//, '').split('/').reduce((o, k) => o[k], raiz);
}

function tipoDe(v) {
  if (v === null) return 'null';
  if (Array.isArray(v)) return 'array';
  if (Number.isInteger(v)) return 'integer';
  return typeof v; // string, number, boolean, object
}

function coincideTipo(v, t) {
  const real = tipoDe(v);
  return real === t || (t === 'number' && real === 'integer');
}

function validar(raiz, esquema, valor, ruta, errores) {
  if (esquema.$ref) return validar(raiz, resolver(raiz, esquema.$ref), valor, ruta, errores);

  if (esquema.oneOf) {
    const aciertos = esquema.oneOf.filter(s => {
      const e = [];
      validar(raiz, s, valor, ruta, e);
      return e.length === 0;
    });
    if (aciertos.length !== 1) errores.push(`${ruta}: no cumple exactamente una de las opciones permitidas`);
    return;
  }

  if (esquema.type) {
    const tipos = Array.isArray(esquema.type) ? esquema.type : [esquema.type];
    if (!tipos.some(t => coincideTipo(valor, t))) {
      errores.push(`${ruta}: tipo ${tipoDe(valor)} no permitido (esperado ${tipos.join('|')})`);
      return;
    }
  }
  if (esquema.enum && !esquema.enum.includes(valor)) errores.push(`${ruta}: valor "${valor}" fuera de la lista permitida`);
  if (typeof valor === 'number') {
    if (esquema.minimum !== undefined && valor < esquema.minimum) errores.push(`${ruta}: ${valor} < ${esquema.minimum}`);
    if (esquema.maximum !== undefined && valor > esquema.maximum) errores.push(`${ruta}: ${valor} > ${esquema.maximum}`);
  }
  if (typeof valor === 'string' && esquema.maxLength !== undefined && valor.length > esquema.maxLength) {
    errores.push(`${ruta}: ${valor.length} caracteres (máx. ${esquema.maxLength})`);
  }
  if (Array.isArray(valor)) {
    if (esquema.maxItems !== undefined && valor.length > esquema.maxItems) errores.push(`${ruta}: ${valor.length} elementos (máx. ${esquema.maxItems})`);
    if (esquema.items) valor.forEach((x, i) => validar(raiz, esquema.items, x, `${ruta}[${i}]`, errores));
  }
  if (tipoDe(valor) === 'object') {
    (esquema.required || []).forEach(k => { if (!(k in valor)) errores.push(`${ruta}.${k}: campo obligatorio ausente`); });
    const props = esquema.properties || {};
    for (const k of Object.keys(valor)) {
      if (props[k]) validar(raiz, props[k], valor[k], `${ruta}.${k}`, errores);
      else if (esquema.additionalProperties === false) errores.push(`${ruta}.${k}: campo no permitido`);
    }
  }
}

// Los modelos de IA se pasan de longitud con frecuencia (p. ej. 205 caracteres donde el esquema admite 200). Eso no es un fallo
// de contenido, así que antes de validar se recortan en el sitio los textos y listas que exceden maxLength / maxItems.
function recortarExcesos(raiz, esquema, valor) {
  if (!esquema || valor === null || typeof valor !== 'object') return valor;
  if (esquema.$ref) return recortarExcesos(raiz, resolver(raiz, esquema.$ref), valor);
  if (esquema.oneOf) {
    const rama = esquema.oneOf.find(s => !s.type || coincideTipo(valor, s.type) || s.$ref);
    return rama ? recortarExcesos(raiz, rama, valor) : valor;
  }
  if (Array.isArray(valor)) {
    if (esquema.maxItems !== undefined && valor.length > esquema.maxItems) valor.length = esquema.maxItems;
    valor.forEach((x, i) => {
      if (esquema.items && typeof x === 'string' && esquema.items.maxLength !== undefined && x.length > esquema.items.maxLength) {
        valor[i] = x.slice(0, esquema.items.maxLength - 1) + '…';
      } else if (esquema.items) recortarExcesos(raiz, esquema.items, x);
    });
    return valor;
  }
  const props = esquema.properties || {};
  for (const k of Object.keys(valor)) {
    const s = props[k];
    if (!s) continue;
    const v = valor[k];
    if (typeof v === 'string' && s.maxLength !== undefined && v.length > s.maxLength) valor[k] = v.slice(0, s.maxLength - 1) + '…';
    else recortarExcesos(raiz, s, v);
  }
  return valor;
}

// Devuelve { ok, errores } validando `dato` contra $defs[nombreDef] del esquema (tras recortar textos demasiado largos).
function validarContraDef(esquema, nombreDef, dato) {
  const errores = [];
  recortarExcesos(esquema, esquema.$defs[nombreDef], dato);
  validar(esquema, esquema.$defs[nombreDef], dato, nombreDef, errores);
  // Regla de coherencia que el esquema no expresa: es_caso=false exige motivo.
  if (nombreDef === 'extraccion' && dato && dato.es_caso === false && !dato.motivo_no_caso) {
    errores.push('extraccion.motivo_no_caso: obligatorio cuando es_caso=false');
  }
  return { ok: errores.length === 0, errores };
}


// Lectura de la respuesta de la IA, igual para Gemini y Claude (y para el nodo nativo o la llamada HTTP).
function textoIA(j) {
  if (!j) return '';
  // Claude (nodo Anthropic): content = [{ type: 'text', text }]
  if (Array.isArray(j.content)) return j.content.filter(c => c.type === 'text').map(c => c.text).join('');
  // Gemini (llamada HTTP o nodo con "Simplify" desactivado): candidates[0].content.parts[].text
  if (Array.isArray(j.candidates) && j.candidates[0]) {
    const partes = (j.candidates[0].content && j.candidates[0].content.parts) || [];
    return partes.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join('');
  }
  // Gemini (nodo con "Simplify" activado): content = { parts: [...] }
  if (j.content && Array.isArray(j.content.parts)) return j.content.parts.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join('');
  if (typeof j.mergedResponse === 'string') return j.mergedResponse;
  return '';
}

// Por qué terminó la respuesta (para avisar de un corte por límite de tokens).
function finIA(j) {
  if (!j) return '';
  if (j.stop_reason) return String(j.stop_reason);
  if (Array.isArray(j.candidates) && j.candidates[0] && j.candidates[0].finishReason) return String(j.candidates[0].finishReason);
  return j.finishReason ? String(j.finishReason) : '';
}

// Mensaje del error de la API cuando no hay respuesta (cuota agotada, sobrecarga, clave inválida…).
function errorIA(j) {
  const e = j && j.error;
  if (!e) return '';
  const m = typeof e === 'string' ? e : (e.message || JSON.stringify(e));
  const d = e && e.description ? ' — ' + e.description : ''; // p. ej. "API key not valid"
  return (String(m) + d).slice(0, 260);
}

// Texto de la respuesta o, si no hay, el motivo. Los errores de API empiezan siempre por "Sin respuesta del modelo".
function leerIA(j, errores) {
  const t = textoIA(j);
  if (!t) errores.push('Sin respuesta del modelo' + (errorIA(j) ? ': ' + errorIA(j) : ''));
  else if (/MAX_TOKENS|max_tokens/.test(finIA(j))) errores.push('Respuesta cortada por el límite de tokens (sube max_tokens en parametros.json)');
  return t;
}

const cfg = $('Cargar configuración').first().json;
const p = cfg.parametros;
const NODO_PREVIO = 'Preparar prompt clasificación';

function extraerJson(t) {
  const s = t.replace(/```(?:json)?/gi, '');
  const a = s.indexOf('{');
  const b = s.lastIndexOf('}');
  return a >= 0 && b > a ? s.slice(a, b + 1) : s;
}

return $input.all().map((it, k) => {
  const base = $(NODO_PREVIO).itemMatching(k).json;
  const errores = [];
  const texto = leerIA(it.json, errores);
  let cls = null;
  if (texto) {
    try { cls = JSON.parse(extraerJson(texto)); } catch (e) { errores.push('JSON no parseable: ' + e.message); }
  }
  if (cls) errores.push(...validarContraDef(cfg.schema, 'clasificacion', cls).errores);

  if (errores.length) {
    // Un fallo de la API (cuota, sobrecarga…) no es culpa del artículo: se "omite" sin guardarlo, para reintentarlo en la siguiente ejecución.
    const falloApi = errores.some(e => e.startsWith('Sin respuesta del modelo'));
    return {
      json: {
        id: base.id, url: base.url, url_normalizada: base.url_normalizada, titular: base.titular, fuente: base.fuente,
        acceso: base.acceso, destino: falloApi ? 'omitidos' : 'descartados', etapa: 'clasificacion',
        motivo: ('Clasificación inválida: ' + errores.join('; ')).slice(0, 300),
      },
    };
  }

  const w = p.pesos_puntuacion;
  const suma = Object.keys(w).reduce((s, c) => s + w[c] * cls[c], 0);
  const pesos = Object.values(w).reduce((s, x) => s + x, 0);
  cls.puntuacion_total = Math.round((suma / pesos) / 5 * 100);

  return {
    json: {
      destino: 'casos',
      caso: {
        metadatos: {
          id: base.id, url: base.url, url_normalizada: base.url_normalizada, titular: base.titular,
          fuente: base.fuente, tipo_fuente: base.tipo_fuente, region_fuente: base.region_fuente,
          fecha_publicacion: base.fecha_publicacion, idioma: base.idioma, acceso: base.acceso,
          origen: base.origen || 'rss', ...(base.consulta ? { consulta: base.consulta } : {}),
          fecha_ingesta: new Date().toISOString(),
          modelo_extraccion: p.modelos.extraccion, modelo_clasificacion: p.modelos.clasificacion,
        },
        extraccion: base.extraccion,
        clasificacion: cls,
      },
    },
  };
});

// ALMACENAMIENTO · fila de la hoja "descartados". Los artículos "omitidos" (fallo de la API de IA) no se guardan: se reintentarán.
return $input.all()
  .filter(it => it.json.destino === 'descartados')
  .map(it => ({
    json: {
      fecha: new Date().toISOString(),
      fuente: it.json.fuente,
      titular: it.json.titular,
      etapa: it.json.etapa,
      motivo: it.json.motivo,
      url: it.json.url,
      acceso: it.json.acceso,
      id: it.json.id,
      url_normalizada: it.json.url_normalizada,
    },
  }));

// ALMACENAMIENTO · fila de la hoja "log_ejecuciones" (mismas columnas que el workflow 01; aquí "artículos leídos" = candidatos devueltos por la búsqueda).
const cfg = $('Cargar configuración').first().json;
const seguro = f => { try { return f(); } catch (e) { return []; } };
const n = nodo => seguro(() => $(nodo).all()).filter(i => i.json && i.json.url).length;

const candidatos = n('Extraer candidatos');
const tras_dominios = n('Filtrar dominios conocidos');
const tras_dedup = n('Deduplicar candidatos');
const a_procesar = n('Limitar lote diario');
const consultas_fallidas = seguro(() => $('Extraer candidatos').all()).filter(i => i.json && i.json.error);
const descargados = seguro(() => $('Extraer texto limpio').all()).filter(i => i.json && i.json.url);
const finales = seguro(() => $('Unir resultados').all()).filter(i => i.json && i.json.destino);

const por_etapa = e => finales.filter(i => i.json.destino === 'descartados' && i.json.etapa === e).length;
const guardados = finales.filter(i => i.json.destino === 'casos').length;
const omitidos = finales.filter(i => i.json.destino === 'omitidos').length;
const fin = new Date();

const fila = {
    run_id: cfg.run_id,
    workflow: '03_descubrimiento',
    fecha_inicio: cfg.inicio_iso,
    fecha_fin: fin.toISOString(),
    duracion_s: Math.round((fin - new Date(cfg.inicio_iso)) / 1000),
    ventana_dias: cfg.ventana_dias,
    fuentes_activas: 0,
    fuentes_con_error: consultas_fallidas.length,
    consultas_busqueda: cfg.consultas.length,
    filtrados_dominio_conocido: candidatos - tras_dominios,
    articulos_leidos: candidatos,
    filtrados_fecha: 0,
    filtrados_palabras_clave: 0,
    duplicados: tras_dominios - tras_dedup,
    recortados_por_tope: tras_dedup - a_procesar,
    descargados_completos: descargados.filter(i => i.json.acceso === 'completo').length,
    descargados_parciales: descargados.filter(i => i.json.acceso === 'parcial').length,
    extraidos_ok: guardados + por_etapa('es_caso') + por_etapa('clasificacion'),
    no_son_caso: por_etapa('es_caso'),
    extraccion_invalida: por_etapa('extraccion'),
    clasificacion_invalida: por_etapa('clasificacion'),
    casos_guardados: guardados,
    errores: [...(consultas_fallidas.slice(0, 10).map(e => `${e.json.consulta}: ${e.json.error}`)), ...(omitidos ? [`${omitidos} artículos omitidos por fallo de la API de IA (se reintentarán en la siguiente ejecución)`] : [])].join(' | '),
};
// Orden de columnas pensado para leer la hoja: primero lo importante, al final lo técnico.
const ORDEN = ["fecha_inicio","workflow","casos_guardados","articulos_leidos","filtrados_fecha","filtrados_palabras_clave","duplicados","recortados_por_tope","descargados_completos","descargados_parciales","extraidos_ok","no_son_caso","extraccion_invalida","clasificacion_invalida","fuentes_activas","fuentes_con_error","consultas_busqueda","filtrados_dominio_conocido","ventana_dias","duracion_s","errores","fecha_fin","run_id"];
return [{ json: Object.fromEntries(ORDEN.map(k => [k, fila[k]])) }];
